#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-shader. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/MushroomBlast/Plan.md  ·  ground explosion, ~3 m mushroom column, stylized orange fire, ~2 s, camera 3/4 40°.
    // Smoke = art lead rule "khói vụ nổ" (2026-11-04): eroding sphere mass on VFX/FX/Erode Sphere, numbers from GroundBlast v5c,
    // laid out as stem + cap + ground skirt (differs from GroundBlast's single dome).
    public static class MushroomBlastBuild
    {
        const string Effect = "MushroomBlast";
        const string Root = "Assets/VFX/" + Effect;
        const string Lib = "Assets/Library/";
        // true = smoke is ONE mushroom mesh from Blender (v3 test); false = stem / cap / skirt sphere clusters (v2)
        const bool CloudMesh = true;

        static readonly Color Core = Hex("#FFF3C4"), Mid = Hex("#FF9A3C"), Outer = Hex("#C8281E");
        static readonly Color Charcoal = new Color(0.25f, 0.23f, 0.24f, 1f);

        [MenuItem("VFX/" + Effect + "/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes");

            // 1. Textures. Library files are shared: load only, never re-import (art lead 2026-11-04).
            var tFlash = Load<Texture2D>(Lib + "impact/impact_016.png");   // spiky toon star
            var tWave = Load<Texture2D>(Lib + "wave/wave_004.png");        // crisp ring
            var tGlow = Load<Texture2D>(Lib + "glow/glow_023.png");        // soft blob
            var tSpark = Load<Texture2D>(Lib + "glow/glow_072.png");       // comet, head on the left = flight direction
            // copies (need alpha from brightness for alpha blend): decals_001 -> Scorch, impact_077 (2x2 chunks) -> Debris
            var tScorch = ImportTexture(Root + "/Textures/T_MushroomBlast_Scorch.png", 512, alphaFromGray: true);
            var tDebris = ImportTexture(Root + "/Textures/T_MushroomBlast_Debris.png", 256, alphaFromGray: true);
            // explosion smoke mask + ramp from GroundBlast (load only). _TEMP mask comes from the reference video: do not ship.
            var tErode = Load<Texture2D>("Assets/VFX/GroundBlast/Textures/T_GroundBlast_SmokeErode_TEMP.png");
            var tRamp = Load<Texture2D>("Assets/VFX/GroundBlast/Textures/T_GroundBlast_SmokeRamp.png");
            var sphere = LoadMesh("Assets/VFX/_Imported/Mesh/SM_VFX_SphereUV.fbx");

            // 2. Materials (reused shaders only)
            var mFlash = Material(M("Flash_Add"), VfxBlend.Additive, tFlash);
            var mWave = Material(M("Shockwave_Add"), VfxBlend.Additive, tWave);
            var mFire = Material(M("FireCore_Add"), VfxBlend.Additive, tGlow);
            var mSpark = Material(M("Spark_Add"), VfxBlend.Additive, tSpark);
            var mScorch = Material(M("Scorch_Alpha"), VfxBlend.Alpha, tScorch);
            var mDebris = Material(M("Debris_Alpha"), VfxBlend.Alpha, tDebris);
            var mSmoke = Material(M("Smoke_Alpha"), VfxBlend.Alpha, tErode, shaderName: "VFX/FX/Erode Sphere");
            mSmoke.SetTexture("_RampTex", tRamp);
            mSmoke.SetFloat("_EmisBoost", 1.1f);
            mSmoke.SetFloat("_HeatRange", 0.35f);
            mSmoke.SetFloat("_ShadowTone", 0.3f);
            mSmoke.SetFloat("_Lumps", 0.22f);
            EditorUtility.SetDirty(mSmoke);

            // 3. Root = layer 1 Flash (art lead: the prefab root is itself a Particle System)
            var rootGo = new GameObject("VFX_" + Effect);
            var flash = ParticleOn(rootGo, mFlash, lifetime: 0.12f, size: 3.5f, color: Core);
            var fs = flash.shape; fs.enabled = true; fs.shapeType = ParticleSystemShapeType.Sphere;
            fs.radius = 0.001f; fs.position = new Vector3(0f, 0.6f, 0f);    // lifted so the ground does not cut the star
            var fm = flash.main; fm.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 0.5f);
            SizeOverLifetime(flash, 0f, 0.6f, 0.25f, 1f, 1f, 0.7f);
            AlphaOverLifetime(flash, 0f, 1f, 0.5f, 1f, 1f, 0f);
            Sorting(flash, 2);
            var root = rootGo.transform;

            // 2. Shockwave: flat ring on the ground (Billboard + Local), 0.5 -> 5 m, ease-out
            var wave = Particle(root, "Shockwave", mWave, lifetime: 0.4f, size: 5f, color: Color.white);
            Flat(wave, 0.02f);
            SizeOverLifetime(wave, 0f, 0.1f, 0.25f, 0.65f, 1f, 1f);
            ColorOverLifetime(wave, new[] { Core, Mid, Outer }, 0f, 1f, 0.5f, 0.6f, 1f, 0f);
            Sorting(wave, -4);

            // 9. Scorch: dark cracked mark on the ground, holds, fades over the last 0.5 s
            var scorch = Particle(root, "Scorch", mScorch, lifetime: 1.95f, size: 2.6f, color: new Color(0.1f, 0.06f, 0.04f, 1f));
            Flat(scorch, 0.01f);
            Burst(scorch, 1, 0.05f);
            var scm = scorch.main; scm.duration = 2f; scm.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            AlphaOverLifetime(scorch, 0f, 0f, 0.04f, 0.9f, 0.75f, 0.9f, 1f, 0f);
            Sorting(scorch, -5);

            float meshD = Mathf.Max(0.01f, sphere.bounds.size.x);   // mesh diameter -> start size in metres

            if (CloudMesh)
            {
                // 4-6 v3 (art lead: "dùng mcp blender tạo 1 mesh hình nấm thay vì dùng nhiều khối sphere"): ONE mushroom mesh
                // made in Blender from metaballs (stem + cap with rolled rim + ground skirt, lumpy, 3000 tris, cylindrical UV:
                // u around x2, v up; script Docs/VFX/MushroomBlast/mushroom_mesh_blender.py). Same shader with _MESH_NORMAL
                // (light from mesh normals). Grows from the ground: height shoots up first, width follows.
                var cloudMesh = LoadMesh(Root + "/Mesh/SM_MushroomBlast_Cloud.fbx");
                var mCloud = Material(M("Cloud_Alpha"), VfxBlend.Alpha, tErode, shaderName: "VFX/FX/Erode Sphere");
                mCloud.CopyPropertiesFromMaterial(mSmoke);
                mCloud.SetFloat("_Lumps", 0.06f);                     // the mesh is already lumpy
                // v3b: v3 mask was one 4 m tile -> big vertical fire strokes, eroded in large sheets with straight cuts
                mCloud.SetTextureScale("_MainTex", new Vector2(3f, 2.5f));
                mCloud.SetFloat("_ShadowTone", 0.35f);                // with the 2-tone toon light: lit top / dark underside
                mCloud.SetFloat("_MeshNormal", 1f); mCloud.EnableKeyword("_MESH_NORMAL");
                EditorUtility.SetDirty(mCloud);
                float h = Mathf.Max(0.01f, cloudMesh.bounds.size.y);
                var cloud = Smoke(root, "Cloud", mCloud, cloudMesh, 1, 0f, 1.9f, 1.9f, h, 3.2f, 3.2f, 3.2f, 3.2f);   // ~3.2 m tall
                var clm = cloud.main; clm.startColor = new Color(0.34f, 0.31f, 0.32f, 1f);   // v3b: lighter lit side, shadow ~0.12
                var col = cloud.sizeOverLifetime; col.enabled = true; col.separateAxes = true;
                col.x = Lin(0f, 0.35f, 0.14f, 0.9f, 1f, 1.08f);
                col.y = Lin(0f, 0.15f, 0.16f, 0.95f, 1f, 1.05f);
                col.z = Lin(0f, 0.35f, 0.14f, 0.9f, 1f, 1.08f);
                var cv = cloud.velocityOverLifetime; cv.enabled = true; cv.space = ParticleSystemSimulationSpace.Local;
                cv.x = new ParticleSystem.MinMaxCurve(0f); cv.y = new ParticleSystem.MinMaxCurve(0.15f); cv.z = new ParticleSystem.MinMaxCurve(0f);
                Sorting(cloud, -2);
            }
            else
            {
            // 4. Stem: narrow column of 10 spheres shooting up to ~2.2 m (cone up, random speed + drag stacks them)
            // v2: v1 stem all flew up into the cap (cap floated with no stem from 0.7 s) -> slower spread 1-5.5 fills 0.3-2 m, 14 spheres
            var stem = Smoke(root, "Stem", mSmoke, sphere, 14, 0f, 1.6f, 1.9f, meshD, 0.55f, 0.85f, 0.8f, 1.2f);
            var ss = stem.shape; ss.enabled = true; ss.shapeType = ParticleSystemShapeType.Cone;
            ss.angle = 6f; ss.radius = 0.25f; ss.radiusThickness = 1f; ss.rotation = new Vector3(-90f, 0f, 0f);
            var stm = stem.main; stm.startSpeed = new ParticleSystem.MinMaxCurve(1f, 5.5f);
            Drag(stem, 3f, 0.3f);
            Sorting(stem, -2);

            // 5. Cap: 14 large spheres at ~2.3 m spreading sideways (horizontal ring) -> mushroom head ~3 m wide
            var cap = Smoke(root, "Cap", mSmoke, sphere, 14, 0.12f, 1.6f, 1.85f, meshD, 0.8f, 1.2f, 0.7f, 1.0f);
            cap.transform.localPosition = new Vector3(0f, 2.3f, 0f);
            var cs = cap.shape; cs.enabled = true; cs.shapeType = ParticleSystemShapeType.Circle;
            cs.radius = 0.4f; cs.radiusThickness = 1f; cs.rotation = new Vector3(-90f, 0f, 0f);   // circle in the XZ plane
            var cpm = cap.main; cpm.startSpeed = new ParticleSystem.MinMaxCurve(1.5f, 3f);
            Drag(cap, 2.5f, 0.4f);
            Sorting(cap, -1);

            // 6. Skirt: ring of 12 small flat spheres rolling out along the ground
            // v2: v1 puffs flew too far apart and read as separate hollow rings -> slower, bigger, more, overlapping
            var skirt = Smoke(root, "Skirt", mSmoke, sphere, 16, 0.02f, 1.1f, 1.5f, meshD, 0.6f, 0.9f, 0.4f, 0.6f);
            skirt.transform.localPosition = new Vector3(0f, 0.2f, 0f);
            var ks = skirt.shape; ks.enabled = true; ks.shapeType = ParticleSystemShapeType.Circle;
            ks.radius = 0.6f; ks.radiusThickness = 1f; ks.rotation = new Vector3(-90f, 0f, 0f);
            var skm = skirt.main; skm.startSpeed = new ParticleSystem.MinMaxCurve(2.5f, 4f);
            Drag(skirt, 4f, 0.1f);
            Sorting(skirt, -3);
            }

            // 3. FireCore: one strong glow rising with the column, yellow -> orange -> red, out by 0.6 s
            var fire = Particle(root, "FireCore", mFire, lifetime: 0.45f, size: 1.6f, color: Color.white);   // v3b: was a red fog over the smoke at 0.45 s
            fire.transform.localPosition = new Vector3(0f, 0.6f, 0f);
            var fv = fire.velocityOverLifetime; fv.enabled = true; fv.space = ParticleSystemSimulationSpace.Local;
            fv.x = new ParticleSystem.MinMaxCurve(0f); fv.y = new ParticleSystem.MinMaxCurve(3f); fv.z = new ParticleSystem.MinMaxCurve(0f);
            SizeOverLifetime(fire, 0f, 0.5f, 0.2f, 1f, 1f, 1.2f);
            ColorOverLifetime(fire, new[] { Core, Mid, Outer }, 0f, 1f, 0.4f, 1f, 1f, 0f);
            Sorting(fire, 0);

            // 7. Debris: 10 dark rock chunks thrown out, spinning, falling (random frame of the 2x2 sheet, no animation)
            var debris = Particle(root, "Debris", mDebris, lifetime: 1.1f, size: 0.25f, color: Hex("#3A2A20"));
            Burst(debris, 10);
            var dm = debris.main;
            dm.duration = 1.2f;
            dm.startLifetime = new ParticleSystem.MinMaxCurve(0.9f, 1.2f);
            dm.startSize = new ParticleSystem.MinMaxCurve(0.15f, 0.35f);
            dm.startSpeed = new ParticleSystem.MinMaxCurve(5f, 8f);
            dm.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            dm.gravityModifier = 2.2f;
            var ds = debris.shape; ds.enabled = true; ds.shapeType = ParticleSystemShapeType.Cone;
            ds.angle = 40f; ds.radius = 0.3f; ds.rotation = new Vector3(-90f, 0f, 0f);
            var drot = debris.rotationOverLifetime; drot.enabled = true;
            drot.z = new ParticleSystem.MinMaxCurve(-2f * Mathf.PI, 2f * Mathf.PI);
            var dt = debris.textureSheetAnimation; dt.enabled = true;
            dt.mode = ParticleSystemAnimationMode.Grid; dt.numTilesX = 2; dt.numTilesY = 2;
            dt.animation = ParticleSystemAnimationType.WholeSheet;
            dt.frameOverTime = new ParticleSystem.MinMaxCurve(0f, 0.999f);   // constant per particle: random chunk, no animation
            SizeOverLifetime(debris, 0f, 1f, 0.8f, 1f, 1f, 0f);
            Sorting(debris, 1);

            // 8. Sparks: comets (head left = flight direction) flung up and out, falling back, shrinking
            var sparks = Particle(root, "Sparks", mSpark, lifetime: 0.7f, size: 0.25f, color: Core);
            Burst(sparks, 20, 0.02f);
            var sp = sparks.main;
            sp.duration = 0.75f;
            sp.startLifetime = new ParticleSystem.MinMaxCurve(0.4f, 0.7f);
            sp.startSize = new ParticleSystem.MinMaxCurve(0.2f, 0.3f);
            sp.startSpeed = new ParticleSystem.MinMaxCurve(6f, 11f);
            sp.gravityModifier = 1f;
            var sps = sparks.shape; sps.enabled = true; sps.shapeType = ParticleSystemShapeType.Cone;
            sps.angle = 50f; sps.radius = 0.2f; sps.rotation = new Vector3(-90f, 0f, 0f);
            var spl = sparks.limitVelocityOverLifetime; spl.enabled = true; spl.drag = 1.5f;
            SizeOverLifetime(sparks, 0f, 1f, 0.6f, 0.8f, 1f, 0f);
            ColorOverLifetime(sparks, new[] { Core, Mid }, 0f, 1f, 1f, 1f);
            var sr = Rend(sparks);
            sr.renderMode = ParticleSystemRenderMode.Stretch;
            sr.velocityScale = 0.06f;
            sr.lengthScale = 2f;
            Sorting(sparks, 3);

            // 4. Save (each layer = its own component prefab, nested), validate, preview (3/4, 40° down), demo scene
            var prefab = SaveNested(rootGo, Root + "/Prefabs/VFX_" + Effect + ".prefab", Root + "/Prefabs/Components", "CMP_" + Effect + "_");
            var target = new Vector3(0f, 1.4f, 0f);
            const float d = 8f, a = 40f * Mathf.Deg2Rad;
            var cam = target + new Vector3(0f, Mathf.Sin(a) * d, -Mathf.Cos(a) * d);
            Finish(prefab, Root, Effect, new[] { 0.04f, 0.12f, 0.25f, 0.45f, 0.7f, 1.0f, 1.4f, 1.8f }, cam, target);
        }

        public static void BuildBatch() => RunBatch(Build);

        // ---------------------------------------------------------------- local helpers

        static string M(string layer) => Root + "/Materials/M_" + Effect + "_" + layer + ".mat";

        /// <summary>Eroding smoke spheres (GroundBlast v5c setup): mesh render, Y-only rotation, Custom1 phases
        /// burn -> veins -> charcoal -> eaten into strands. Sizes in metres (x/z width, y height).</summary>
        static ParticleSystem Smoke(Transform parent, string name, Material mat, Mesh sphere, int count, float delay,
                                    float lifeMin, float lifeMax, float meshD, float wMin, float wMax, float hMin, float hMax)
        {
            var ps = Particle(parent, name, mat, lifetime: lifeMax, size: 1f, color: Charcoal);
            Burst(ps, count, delay);
            var m = ps.main;
            m.duration = 2f;
            m.startLifetime = new ParticleSystem.MinMaxCurve(lifeMin, lifeMax);
            m.startSize3D = true;
            m.startSizeX = new ParticleSystem.MinMaxCurve(wMin / meshD, wMax / meshD);
            m.startSizeY = new ParticleSystem.MinMaxCurve(hMin / meshD, hMax / meshD);
            m.startSizeZ = new ParticleSystem.MinMaxCurve(wMin / meshD, wMax / meshD);
            m.startRotation3D = true;   // spin only around Y: strands stay vertical
            m.startRotationX = new ParticleSystem.MinMaxCurve(0f);
            m.startRotationY = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            m.startRotationZ = new ParticleSystem.MinMaxCurve(0f);
            m.gravityModifier = 0f;
            SizeOverLifetime(ps, 0f, 0.45f, 0.15f, 0.95f, 1f, 1.15f);
            var cd = ps.customData; cd.enabled = true;
            cd.SetMode(ParticleSystemCustomData.Custom1, ParticleSystemCustomDataMode.Vector);
            cd.SetVectorComponentCount(ParticleSystemCustomData.Custom1, 3);                                                           // shader v4: x, y, z
            cd.SetVector(ParticleSystemCustomData.Custom1, 2, Lin(0f, 0.03f, 1f, 0.03f));                                              // z: edge softness (0.03 crisp)
            cd.SetVector(ParticleSystemCustomData.Custom1, 0, Lin(0f, 0f, 0.5f, 0f, 1f, 1.02f));                                       // x: when the smoke dissolves
            cd.SetVector(ParticleSystemCustomData.Custom1, 1, Lin(0f, 0.9f, 0.06f, 0.7f, 0.14f, 0.3f, 0.22f, 0.1f, 0.3f, -0.1f));     // y: when the fire cools
            var r = Rend(ps);
            r.renderMode = ParticleSystemRenderMode.Mesh;
            r.mesh = sphere;
            r.sortMode = ParticleSystemSortMode.Distance;
            r.SetActiveVertexStreams(new List<ParticleSystemVertexStream> {
                ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Normal, ParticleSystemVertexStream.Color,
                ParticleSystemVertexStream.UV, ParticleSystemVertexStream.Custom1XYZ,ParticleSystemVertexStream.StableRandomX,
                ParticleSystemVertexStream.Center });
            return ps;
        }

        static void Drag(ParticleSystem ps, float drag, float rise)
        {
            var lim = ps.limitVelocityOverLifetime; lim.enabled = true; lim.drag = drag;
            var v = ps.velocityOverLifetime; v.enabled = true; v.space = ParticleSystemSimulationSpace.Local;
            v.x = new ParticleSystem.MinMaxCurve(0f); v.y = new ParticleSystem.MinMaxCurve(rise); v.z = new ParticleSystem.MinMaxCurve(0f);
        }

        /// <summary>Lying on the ground: Billboard + Render Alignment Local, GameObject rotated X 90° (no Horizontal Billboard).</summary>
        static void Flat(ParticleSystem ps, float y)
        {
            ps.transform.localPosition = new Vector3(0f, y, 0f);
            ps.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            Rend(ps).alignment = ParticleSystemRenderSpace.Local;
        }

        static ParticleSystemRenderer Rend(ParticleSystem ps) => ps.GetComponent<ParticleSystemRenderer>();

        static void Sorting(ParticleSystem ps, int order)
        {
            var r = Rend(ps);
            r.sortingOrder = order;
            r.maxParticleSize = 3f;
        }

        static T Load<T>(string path) where T : Object
        {
            var o = AssetDatabase.LoadAssetAtPath<T>(path);
            if (o == null) throw new System.IO.FileNotFoundException("Asset not found: " + path);
            return o;
        }

        /// <summary>Piecewise-LINEAR curve from (time, value) pairs (VfxBuildKit.Curve eases between keys).</summary>
        static ParticleSystem.MinMaxCurve Lin(params float[] tv)
        {
            int n = tv.Length / 2;
            var keys = new Keyframe[n];
            for (int i = 0; i < n; i++) keys[i] = new Keyframe(tv[2 * i], tv[2 * i + 1]);
            for (int i = 0; i < n; i++)
            {
                float inT = i > 0 ? (keys[i].value - keys[i - 1].value) / (keys[i].time - keys[i - 1].time) : 0f;
                float outT = i < n - 1 ? (keys[i + 1].value - keys[i].value) / (keys[i + 1].time - keys[i].time) : 0f;
                keys[i].inTangent = i > 0 ? inT : outT;
                keys[i].outTangent = i < n - 1 ? outT : inT;
            }
            return new ParticleSystem.MinMaxCurve(1f, new AnimationCurve(keys));
        }

        static Mesh LoadMesh(string fbx)
        {
            foreach (var o in AssetDatabase.LoadAllAssetsAtPath(fbx)) if (o is Mesh m) return m;
            throw new System.IO.FileNotFoundException("Mesh not found: " + fbx);
        }

        static Color Hex(string h) => ColorUtility.TryParseHtmlString(h, out var c) ? c : Color.magenta;
    }
}
#endif
